"use client";

import { useEffect, useMemo, useState, type ReactNode } from "react";
import { DataGridBody, DataGridHeader, DataGridProvider, DataGridRoot, defineColumns } from "@/registry/default/components/data-grid/data-grid";
import { useDataGridServerRows } from "@/registry/default/components/data-grid-server/data-grid-server";
import { describeFilterOperators, withColumnMap } from "@/registry/default/components/data-grid-server-query/data-grid-server-query";
import type { LoggedQuery, QueryDemoRow } from "./data-grid-server-query-demo-db";

const columnDefs = defineColumns<QueryDemoRow>()([
  { id: "region", header: "Region", accessorKey: "region", type: "select", width: 120 },
  { id: "make", header: "Make", accessorKey: "make", type: "select", width: 110 },
  { id: "price", header: "Revenue", accessorKey: "price", type: "number", width: 120, aggregate: "sum" },
] as const);

type Demo = Awaited<ReturnType<typeof import("./data-grid-server-query-demo-db").createQueryDemo>>;

const loadDemo = (onQuery: (entry: LoggedQuery) => void) => import("./data-grid-server-query-demo-db").then(({ createQueryDemo }) => createQueryDemo(onQuery));

function PivotGrid({ demo, lastQuery }: { demo: Demo; lastQuery: LoggedQuery | undefined }): ReactNode {
  const columns = useMemo(() => withColumnMap(columnDefs, describeFilterOperators(demo.columns)), [demo.columns]);
  const server = useDataGridServerRows<QueryDemoRow>({
    mode: "scroll",
    getRowId: (row) => String(row.id),
    defaultSpec: {
      sorts: [],
      filters: [],
      searchText: "",
      groupBy: ["region"],
      aggregates: [{ columnId: "price", reducer: "sum" }],
      pivot: { columnIds: ["make"] },
    },
    fetchRows: ({ signal, ...request }) => demo.query.fetchRows(request, { signal }),
  });
  return (
    <div className="flex w-full flex-col gap-2">
      <DataGridProvider {...server.providerProps} columns={columns} readOnly>
        <div className="flex h-[240px] flex-col overflow-hidden rounded-md border border-border">
          <DataGridRoot aria-label="Car sales revenue per region and make, pivoted on the server" className="min-h-0 flex-1 rounded-[inherit] border-none" {...server.rootProps}>
            <DataGridHeader />
            <DataGridBody />
          </DataGridRoot>
        </div>
      </DataGridProvider>
      <div className="rounded-md border border-border bg-muted/40 p-3 text-xs">
        <p className="mb-1 font-medium text-foreground">Last statement</p>
        <pre className="whitespace-pre-wrap break-all font-mono text-foreground">{lastQuery?.sql ?? "None yet."}</pre>
        <pre className="whitespace-pre-wrap break-all font-mono text-muted-foreground">{lastQuery ? `params: ${JSON.stringify(lastQuery.params)}` : null}</pre>
      </div>
    </div>
  );
}

/** A server pivot on an in-browser PostgreSQL: one row per region, one generated column per make, each cell the revenue of the cars sold. */
export default function DataGridServerPivotDemo(): ReactNode {
  const [demo, setDemo] = useState<Demo | null>(null);
  const [lastQuery, setLastQuery] = useState<LoggedQuery>();

  useEffect(() => {
    let cancelled = false;
    void loadDemo(setLastQuery).then((ready) => {
      if (!cancelled) setDemo(ready);
    });
    return () => {
      cancelled = true;
    };
  }, []);

  if (!demo) {
    return <div className="flex h-[300px] w-full items-center justify-center rounded-md border border-border text-sm text-muted-foreground">Starting the in-browser database…</div>;
  }
  return <PivotGrid demo={demo} lastQuery={lastQuery} />;
}

import { PGlite } from "@electric-sql/pglite";
import { boolean, date, integer, pgTable, text } from "drizzle-orm/pg-core";
import { drizzle } from "drizzle-orm/pglite";
import { DEALERSHIPS, MAKES, REGIONS, generateSales } from "./sales-data";
import { columnsFromDrizzleTable, createDrizzleGridQuery } from "@/registry/default/components/data-grid-server-query-drizzle/data-grid-server-query-drizzle";

/** One car sold by a dealership. */
export type QueryDemoRow = {
  id: number;
  soldOn: string;
  region: string;
  dealership: string;
  salesperson: string;
  make: string;
  model: string;
  customer: string;
  price: number;
  discount: number;
  financed: boolean;
};
export type LoggedQuery = { sql: string; params: unknown[] };

const carSales = pgTable("car_sales", {
  id: integer("id").primaryKey(),
  soldOn: date("sold_on", { mode: "string" }).notNull(),
  region: text("region").notNull(),
  dealership: text("dealership").notNull(),
  salesperson: text("salesperson").notNull(),
  make: text("make").notNull(),
  model: text("model").notNull(),
  customer: text("customer").notNull(),
  price: integer("price").notNull(),
  discount: integer("discount").notNull(),
  financed: boolean("financed").notNull(),
});

const ROW_COUNT = 5000;

/** Opens an in-browser PostgreSQL, seeds it with 5,000 fictional car sales, and wires the query layer to it. Every statement the layer runs goes to `onQuery`. */
export async function createQueryDemo(onQuery: (entry: LoggedQuery) => void) {
  const pg = new PGlite();
  await pg.exec(
    "create table car_sales (id integer primary key, sold_on date not null, region text not null, dealership text not null, salesperson text not null, make text not null, model text not null, customer text not null, price integer not null, discount integer not null, financed boolean not null)",
  );
  // The seed names hold no quote, so plain interpolation stays valid SQL.
  const values = generateSales(ROW_COUNT).map((sale, index) => `(${index + 1}, '${sale.soldOn}', '${sale.region}', '${sale.dealership}', '${sale.salesperson}', '${sale.make}', '${sale.model}', '${sale.customer}', ${sale.price}, ${sale.discount}, ${sale.financed})`);
  await pg.exec(`insert into car_sales values ${values.join(", ")}`);
  const db = drizzle(pg, { logger: { logQuery: (sql, params) => onQuery({ sql, params }) } });
  const columns = columnsFromDrizzleTable(carSales, {
    pick: ["id", "soldOn", "region", "dealership", "salesperson", "make", "model", "customer", "price", "discount", "financed"],
    overrides: {
      customer: { searchable: true },
      salesperson: { searchable: true },
      model: { searchable: true },
      region: { type: "select", choices: REGIONS },
      dealership: { type: "select", choices: DEALERSHIPS },
      make: { type: "select", choices: MAKES },
      price: { aggregate: "sum" },
    },
  });
  const query = createDrizzleGridQuery<QueryDemoRow>({ db, table: carSales, columns });
  return { query, columns, total: ROW_COUNT };
}

/** One car sold by a dealership. */
export type SaleRow = {
  id: string;
  soldOn: string;
  region: string;
  dealership: string;
  salesperson: string;
  make: string;
  model: string;
  customer: string;
  price: number;
  discount: number;
  financed: boolean;
};

export const REGIONS = ["North", "South", "East", "West"];
export const DEALERSHIPS = ["Northgate Motors", "Pine Ridge Cars", "Bayview Autos", "Southfield Motors", "Eastbrook Cars", "Harbor Point Motors", "Westlake Autos", "Canyon Road Motors"];
export const MAKES = ["Kestrel", "Marlow", "Nordvik", "Solenne", "Vantor"];
const SALESPEOPLE = ["Dana Brooks", "Eli Moreno", "Fern Walsh", "Gus Ortega", "Hana Ito", "Ivan Petrov", "Jade Lin", "Kofi Mensah", "Lena Fischer", "Milo Grant", "Nia Duarte", "Omar Aziz", "Pia Lund", "Raul Vega", "Sana Mir", "Theo Clark"];
const MODELS = [["Brook", "Glide", "Summit"], ["Coast", "Harbor", "Tide"], ["Birch", "Fjord", "Frost"], ["Dawn", "Lumen", "Opal"], ["Ember", "Flint", "Quarry"]];
// Unequal shares per region and a different make mix in each region, so group totals differ.
const REGION_SLOTS = [0, 0, 0, 0, 1, 1, 1, 2, 2, 3];
const MAKE_MIX = [
  [0, 0, 0, 1, 2, 3, 4, 1],
  [1, 1, 1, 2, 0, 3, 4, 2],
  [2, 2, 3, 3, 3, 0, 1, 4],
  [4, 4, 4, 3, 0, 1, 2, 4],
];
const FIRST = ["Alex", "Sam", "Jordan", "Taylor", "Morgan", "Casey", "Riley", "Jamie", "Avery", "Quinn", "Drew", "Robin"];
const LAST = ["Smith", "Garcia", "Chen", "Patel", "Novak", "Okafor", "Larsen", "Rossi", "Kim", "Silva", "Meyer", "Haddad"];

/** `count` fictional car sales. Index arithmetic instead of `Math.random` keeps the server and client markup equal. */
export const generateSales = (count: number): SaleRow[] =>
  Array.from({ length: count }, (_, index) => {
    const region = REGION_SLOTS[index % REGION_SLOTS.length]!;
    const mix = MAKE_MIX[region]!;
    const make = mix[Math.floor(index / REGION_SLOTS.length) % mix.length]!;
    const model = Math.floor(index / 80) % 3;
    const dealership = region * 2 + (Math.floor(index / 7) % 3 === 0 ? 1 : 0);
    return {
      id: `sale-${index + 1}`,
      soldOn: new Date(Date.UTC(2025, 0, 1 + ((index * 7) % 365))).toISOString().slice(0, 10),
      region: REGIONS[region]!,
      dealership: DEALERSHIPS[dealership]!,
      salesperson: SALESPEOPLE[dealership * 2 + (Math.floor(index / 13) % 2)]!,
      make: MAKES[make]!,
      model: MODELS[make]![model]!,
      customer: `${FIRST[Math.floor(index / 5) % FIRST.length]!} ${LAST[(index * 7) % LAST.length]!}`,
      price: 21000 + make * 6000 + model * 9000 + ((index * 37) % 41) * 100,
      discount: ((index * 7) % 13) * 250,
      financed: index % 3 !== 0,
    };
  });
